"use client";

import {
  createContext,
  useContext,
  useState,
  useCallback,
  useMemo,
  useRef,
  type ComponentProps,
  type ReactNode,
} from "react";
import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/c-ui/provider-alert-dialog";
import { cn } from "@/lib/utils";

export interface AlertOptions {
  title?: string;
  description?: string;
  buttonLabel?: string;
  dismissButtonClassName?: string;
  dismissButtonVariant?: ComponentProps<typeof AlertDialogCancel>["variant"];
  children?: ReactNode;
}

export interface AlertDialogMessages {
  title: string;
  buttonLabel: string;
}

export interface AlertDialogProviderProps {
  children: ReactNode;
  messages?: Partial<AlertDialogMessages>;
}

export interface AlertApi {
  (options: AlertOptions): Promise<void>;
  dismiss: () => void;
}

interface AlertContextType {
  alert: AlertApi;
}

const AlertContext = createContext<AlertContextType | undefined>(undefined);

const DEFAULT_ALERT_MESSAGES: AlertDialogMessages = {
  title: "Notice",
  buttonLabel: "OK",
};

function AlertDialogContent_({
  isOpen,
  title,
  description,
  buttonLabel,
  dismissButtonClassName,
  dismissButtonVariant,
  children,
  onDismiss,
}: {
  isOpen: boolean;
  title: string;
  description: string;
  buttonLabel: string;
  dismissButtonClassName?: string;
  dismissButtonVariant?: ComponentProps<typeof AlertDialogCancel>["variant"];
  children?: ReactNode;
  onDismiss: () => void;
}) {
  return (
    <AlertDialog
      open={isOpen}
      onOpenChange={(open) => {
        if (!open) onDismiss();
      }}
    >
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>{title}</AlertDialogTitle>
          {description ? <AlertDialogDescription>{description}</AlertDialogDescription> : null}
        </AlertDialogHeader>
        {children != null ? <div className="py-2">{children}</div> : null}
        <AlertDialogFooter className="justify-center sm:justify-center">
          <AlertDialogCancel
            className={cn(
              "min-w-24 transition-transform duration-150 active:scale-[0.97]",
              dismissButtonClassName,
            )}
            variant={dismissButtonVariant ?? "default"}
          >
            {buttonLabel}
          </AlertDialogCancel>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

export const AlertDialogProvider = ({ children, messages }: AlertDialogProviderProps) => {
  const [options, setOptions] = useState<AlertOptions>({});
  const [isOpen, setIsOpen] = useState(false);
  const resolverRef = useRef<(() => void) | null>(null);
  const resolvedMessages = {
    ...DEFAULT_ALERT_MESSAGES,
    ...messages,
  };

  const resolvePending = useCallback(() => {
    const resolver = resolverRef.current;
    if (resolver) resolver();
    resolverRef.current = null;
  }, []);

  const handleDismiss = useCallback(() => {
    resolvePending();
    setIsOpen(false);
  }, [resolvePending]);

  const alertFn = useCallback(
    (alertOptions: AlertOptions) => {
      resolvePending();
      setOptions(alertOptions);
      setIsOpen(true);
      return new Promise<void>((resolve) => {
        resolverRef.current = resolve;
      });
    },
    [resolvePending],
  );

  const alert = useMemo(
    // eslint-disable-next-line react-hooks/refs
    () => Object.assign(alertFn, { dismiss: handleDismiss }),
    [alertFn, handleDismiss],
  );

  return (
    <AlertContext.Provider value={{ alert }}>
      {children}
      <AlertDialogContent_
        isOpen={isOpen}
        title={options.title ?? resolvedMessages.title}
        description={options.description ?? ""}
        buttonLabel={options.buttonLabel ?? resolvedMessages.buttonLabel}
        dismissButtonClassName={options.dismissButtonClassName}
        dismissButtonVariant={options.dismissButtonVariant}
        onDismiss={handleDismiss}
      >
        {options.children}
      </AlertDialogContent_>
    </AlertContext.Provider>
  );
};

export const useAlert = () => {
  const context = useContext(AlertContext);
  if (!context) {
    throw new Error("useAlert must be used within an AlertDialogProvider");
  }
  return context.alert;
};

"use client";

import * as React from "react";
import { AlertDialog as AlertDialogPrimitive } from "@base-ui/react/alert-dialog";
import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";

function AlertDialog({ ...props }: AlertDialogPrimitive.Root.Props) {
  return <AlertDialogPrimitive.Root data-slot="alert-dialog" {...props} />;
}

function AlertDialogTrigger({ ...props }: AlertDialogPrimitive.Trigger.Props) {
  return <AlertDialogPrimitive.Trigger data-slot="alert-dialog-trigger" {...props} />;
}

function AlertDialogPortal({ ...props }: AlertDialogPrimitive.Portal.Props) {
  return <AlertDialogPrimitive.Portal data-slot="alert-dialog-portal" {...props} />;
}

function AlertDialogOverlay({
  className,
  ...props
}: Omit<AlertDialogPrimitive.Backdrop.Props, "className"> & { className?: string }) {
  return (
    <AlertDialogPrimitive.Backdrop
      data-slot="alert-dialog-overlay"
      className={cn(
        "fixed inset-0 isolate z-50 bg-black/10 duration-100 supports-backdrop-filter:backdrop-blur-xs motion-reduce:animate-none motion-reduce:transition-none data-open:animate-in data-open:fade-in-0 data-closed:animate-out data-closed:fade-out-0",
        className,
      )}
      {...props}
    />
  );
}

function AlertDialogContent({
  className,
  size = "default",
  ...props
}: Omit<AlertDialogPrimitive.Popup.Props, "className"> & { className?: string } & {
  size?: "default" | "sm";
}) {
  return (
    <AlertDialogPortal>
      <AlertDialogOverlay />
      <AlertDialogPrimitive.Popup
        data-slot="alert-dialog-content"
        data-size={size}
        className={cn(
          "group/alert-dialog-content fixed top-1/2 left-1/2 z-50 grid w-full -translate-x-1/2 -translate-y-1/2 gap-4 rounded-xl bg-background p-4 ring-1 ring-foreground/10 duration-100 outline-none data-[size=default]:max-w-xs data-[size=sm]:max-w-xs motion-reduce:animate-none motion-reduce:transition-none data-[size=default]:sm:max-w-sm data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95",
          className,
        )}
        {...props}
      />
    </AlertDialogPortal>
  );
}

function AlertDialogHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-dialog-header"
      className={cn(
        "grid grid-rows-[auto_1fr] place-items-center gap-1.5 text-center has-data-[slot=alert-dialog-media]:grid-rows-[auto_auto_1fr] has-data-[slot=alert-dialog-media]:gap-x-4 sm:group-data-[size=default]/alert-dialog-content:place-items-start sm:group-data-[size=default]/alert-dialog-content:text-left sm:group-data-[size=default]/alert-dialog-content:has-data-[slot=alert-dialog-media]:grid-rows-[auto_1fr]",
        className,
      )}
      {...props}
    />
  );
}

function AlertDialogFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-dialog-footer"
      className={cn(
        "-mx-4 -mb-4 flex flex-col-reverse gap-2 rounded-b-xl border-t bg-muted/50 p-4 group-data-[size=sm]/alert-dialog-content:grid group-data-[size=sm]/alert-dialog-content:grid-cols-2 sm:flex-row sm:justify-end",
        className,
      )}
      {...props}
    />
  );
}

function AlertDialogMedia({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-dialog-media"
      className={cn(
        "mb-2 inline-flex size-10 items-center justify-center rounded-md bg-muted sm:group-data-[size=default]/alert-dialog-content:row-span-2 *:[svg:not([class*='size-'])]:size-6",
        className,
      )}
      {...props}
    />
  );
}

function AlertDialogTitle({
  className,
  ...props
}: Omit<React.ComponentProps<typeof AlertDialogPrimitive.Title>, "className"> & {
  className?: string;
}) {
  return (
    <AlertDialogPrimitive.Title
      data-slot="alert-dialog-title"
      className={cn(
        "text-base font-medium sm:group-data-[size=default]/alert-dialog-content:group-has-data-[slot=alert-dialog-media]/alert-dialog-content:col-start-2",
        className,
      )}
      {...props}
    />
  );
}

function AlertDialogDescription({
  className,
  ...props
}: Omit<React.ComponentProps<typeof AlertDialogPrimitive.Description>, "className"> & {
  className?: string;
}) {
  return (
    <AlertDialogPrimitive.Description
      data-slot="alert-dialog-description"
      className={cn(
        "text-sm text-balance text-muted-foreground md:text-pretty *:[a]:underline *:[a]:underline-offset-3 *:[a]:hover:text-foreground",
        className,
      )}
      {...props}
    />
  );
}

function AlertDialogAction({
  className,
  ...props
}: Omit<React.ComponentProps<typeof Button>, "className"> & { className?: string }) {
  return <Button data-slot="alert-dialog-action" className={cn(className)} {...props} />;
}

function AlertDialogCancel({
  className,
  variant = "outline",
  size = "default",
  ...props
}: Omit<AlertDialogPrimitive.Close.Props, "className"> & { className?: string } & Pick<
    Omit<React.ComponentProps<typeof Button>, "className"> & { className?: string },
    "variant" | "size"
  >) {
  return (
    <AlertDialogPrimitive.Close
      data-slot="alert-dialog-cancel"
      className={cn(className)}
      render={<Button variant={variant} size={size} />}
      {...props}
    />
  );
}

export {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogMedia,
  AlertDialogOverlay,
  AlertDialogPortal,
  AlertDialogTitle,
  AlertDialogTrigger,
};
